            new Quote { Id = "https://tr.wikiquote.org/wiki/Elif_Şafak", Text = "Uzaklaşırsın. Yol seni nereye götürürse. Yazı seni nereye sürüklerse. Burnunda bir sızı. Ne de olsa her yolculuk geri dönememe ihtimalini taşır bağrında.", Author = "Elif Şafak" },
