            new Quote { Id = "https://tr.wikiquote.org/wiki/Elif_Şafak", Text = "Özgürlük çıkış kapılarının gümüşi aralığında.", Author = "Elif Şafak" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Elif_Şafak", Text = "Tebeşirle çizilmiş bir seksek oyunu kadar uçucu bir çizgisi vardır hayatın. Farkında olmadan basıyorsun çizgiye. Kızıyorlar anında \"Yandın!\" diye atılıyorsun oyun dışına.", Author = "Elif Şafak" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Elif_Şafak", Text = "Aşk gibiydi okumak da… Neden, nasıl müptelası olduğunu, bilen zaten gayet iyi bilirdi; bilmeyene de anlatamazdın bir türlü.", Author = "Elif Şafak" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Elif_Şafak", Text = "Kanat çırpan kuşlara bakın. Kanatlarının nasıl hareket ettiğine dikkat buyurun, bir aşağı bir yukarı. Bir hüzün, bir saadet. Böyledir hayat. Hoş bir kararda, ahenk içinde, dengede.", Author = "Elif Şafak" },
